import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第二十卦 觀 風地觀 巽上坤下","description":"周易 - 第二十卦 觀 風地觀 巽上坤下","frontmatter":{"title":"第二十卦 觀 風地觀 巽上坤下","description":"周易 - 第二十卦 觀 風地觀 巽上坤下"},"headers":[],"relativePath":"classics/zhouyi/021.md","filePath":"classics/zhouyi/021.md"}'),l={name:"classics/zhouyi/021.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="觀" tabindex="-1">觀 <a class="header-anchor" href="#觀" aria-label="Permalink to “觀”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>盥而不薦，有孚□若。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>大觀在上，順而巽，中正以觀天下。觀，盥而不薦，有孚顒若，下觀而化也。觀天之神道，而四時不忒，聖人以神道設教，而天下服矣。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>風行地上，觀；先王以省方，觀民設教。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>童觀，小人無咎，君子吝。象 曰：初六童觀，小人道也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>窺觀，利女貞。象曰：窺觀女貞，亦可醜也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>觀我生，進退。象曰：觀我生，進退；未失道也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>觀國之光，利用賓於王。象曰：觀國之光，尚賓也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>觀我生，君子無咎。象曰：觀我生，觀民也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>觀其生，君子無咎。象曰：觀其生，志未平也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
